// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: from address, callee-address (we will deploy a helper and pass its address),
    // dynamic arrays for _tos and v (length must be >0 per contract requirement)
    function testFuzz_property(address from, address /*unused*/, address /*unused2*/, bytes memory seed, uint256 len) public {
        // We need at least one element in _tos per require(_tos.length > 0).
        // Build simple arrays from fuzzed inputs but ensure non-empty and reasonable length (bound keeps wide).
        uint256 n = bound(len, 1, 10); // keep array length between 1 and 10

        address[] memory tos = new address[](n);
        uint[] memory vals = new uint[](n);

        // Populate using keccak seeded with fuzzed seed to get varied addresses and values
        for (uint i = 0; i < n; i++) {
            bytes32 h = keccak256(abi.encodePacked(seed, i));
            // derive an address (many will be EOAs with no code), but we must ensure the callee has code
            // so deploy a minimal Forwarder that will accept calls and return true from its fallback via default behavior
            // We'll instead deploy a single Callee helper below and reuse its address for all _tos entries.
            vals[i] = uint(uint256(h));
        }

        // Deploy a benign callee contract that accepts the low-level call and returns true for transferFrom selector.
        // This ensures the internal calls inside C succeed (so both reference and mutant complete without revert)
        Callee ben = new Callee();

        for (uint i = 0; i < n; i++) {
            tos[i] = address(ben);
            // reduce values to a small range to be realistic
            vals[i] = vals[i] % 1000;
        }

        // Now call c.transfer and capture its boolean return using try/catch to observe non-revert completion and return value.
        bool ok;
        try c.transfer(from, address(ben), tos, vals) returns (bool ret) {
            // c.transfer completed; record whether it returned true
            ok = ret;
        } catch {
            // if it reverted, set ok = false to indicate failure (but reference should not revert for these inputs)
            ok = false;
        }

        // General rule: for any non-empty _tos, the reference returns true; the mutant returns false for some inputs.
        // Assert that c.transfer(...) returned true. This holds for the reference for all admissible inputs and
        // is violated by the mutant (which returns false).
        assertTrue(ok);
    }
}

// Minimal benign callee that implements a transferFrom-like function and returns true
contract Callee {
    // match selector transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    // A fallback to accept other low-level calls if any
    fallback() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: from address (fuzzed), amounts packed in uint[] values via a single uint (we'll bound length and amounts), and an index to choose length
    function testFuzz_property(address from, uint256 seed, uint8 len) public {
        // Keep length reasonable but allow 1..5
        uint256 _len = uint256(bound(len, 1, 5));

        // Build arrays
        address[] memory tos = new address[](_len);
        uint[] memory vals = new uint[](_len);

        // Deploy an adversarial callee that always reverts to distinguish behavior
        Reverter rev = new Reverter();

        // Fill arrays: all entries point to the reverting callee; amounts from seed
        for (uint i = 0; i < _len; i++) {
            tos[i] = address(rev);
            // derive pseudo-random amounts from seed so fuzzer can vary them
            vals[i] = uint256(keccak256(abi.encodePacked(seed, i)));
        }

        // Call transfer and observe whether it completes (ok) or reverts
        bool ok;
        try c.transfer(from, address(rev), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for any admissible inputs with non-empty tos, the correct contract performs the external calls
        // and thus a callee that always reverts should cause the call to revert (ok == false). The mutant that returns early
        // would make ok == true for some inputs. Assert that the call did NOT succeed.
        assertTrue(!ok);
    }
}

// Adversarial helper: always revert on any call
contract Reverter {
    fallback() external payable {
        revert("reverter");
    }
}
